const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < input.length && input[offset] <= 32) {
            offset++;
        }
        if (offset >= input.length) return null;
        let num = 0;
        while (offset < input.length && input[offset] > 32) {
            num = num * 10 + (input[offset] - 48);
            offset++;
        }
        return num;
    }

    const N = nextInt();
    if (N === null) return;

    const L = new Int32Array(N);
    let totalLength = 0n;

    for (let i = 0; i < N; i++) {
        L[i] = nextInt();
        totalLength += BigInt(L[i]);
    }

    if (totalLength % 2n !== 0n) {
        process.stdout.write("N\n");
        return;
    }

    const half = totalLength / 2n;

    let pairs = 0;
    let currentDist = 0n;
    let j = 0;

    for (let i = 0; i < N; i++) {
        while (currentDist < half) {
            currentDist += BigInt(L[j]);
            j = (j + 1) % N;
        }

        if (currentDist === half) {
            pairs++;
            if (pairs >= 2) {
                process.stdout.write("S\n");
                return;
            }
        }

        currentDist -= BigInt(L[i]);
    }

    process.stdout.write("N\n");
}

solve();
